export const dishes=rows.map(([type,name,state,ingredients,description,international],i)=>{
 const base=ingredients[0],quantities=Object.fromEntries(ingredients.map(n=>[n,sampleQuantity(n,type.includes('Snack')?'Snack':type.includes('Palya')?'Palya':'Curry',n===base)]));
 Object.assign(quantities,{'Coriander leaves':{quantity:.5,unit:'bunch'},'Cooking oil (unspecified)':{quantity:.03,unit:'litre'},Salt:{quantity:.01,unit:'kg'},'Fennel seeds':{quantity:.005,unit:'kg'},'Fenugreek seeds':{quantity:.003,unit:'kg'},'Coriander seeds':{quantity:.01,unit:'kg'},'Chilli powder':{quantity:.003,unit:'kg'},'Green cardamom':{quantity:.001,unit:'kg'},Milk:{quantity:.4,unit:'litre'}});
 const noOil=/sambol|salad|kosambari|chaat|hummus|pitika|chokha|pico de gallo|curd poha/i.test(name);
 return {id:'menu28-'+i,type,name,state,country:international?state:null,international,base,unit:quantities[base].unit,ingredients,description,quantities,noOil,introduced:'2026-11-14'};
});
export function dailyIdeas(getQuote,{date,type='Curry',state='',query='',all=false}={}){
 const candidates=dishes.filter(d=>d.type===type&&(!state||d.state===state)&&(!query||[d.name,d.state,...d.ingredients].join(' ').toLowerCase().includes(query.toLowerCase()))).map(d=>{const quote=getQuote(d.base,d.unit),estimate=estimateDish(d,getQuote);return {...d,quote,score:quote?quote.price:null,estimate};}).sort((a,b)=>a.estimate.missing-b.estimate.missing||a.estimate.perPortion-b.estimate.perPortion||a.name.localeCompare(b.name));
 if(all||candidates.length<=8)return candidates;
 const day=Math.floor(Date.parse(date+'T12:00:00Z')/86400000),pool=candidates.slice(0,30),offset=((day%pool.length)+pool.length)%pool.length;
 const featured=[],associations=new Set();
 for(let i=0;i<pool.length&&featured.length<8;i++){const d=pool[(offset+i)%pool.length];if(!associations.has(d.state)){featured.push(d);associations.add(d.state);}}
 for(let i=0;featured.length<8&&i<pool.length;i++){const d=pool[(offset+i)%pool.length];if(!featured.includes(d))featured.push(d);}
 return featured;
}
